      "name": "HMX Crisp Linear Switches (18 Pack)",
      "description": "HMX Crisp Linear Switches (18 Pack) la san pham custom keyboard duoc chon loc cho thi truong Viet Nam, huong den nguoi dung can su on dinh, de nang cap va dung tot cho ca game lan cong viec. Dong switch nay thuoc nhom linear, duoc huong den muc tieu can bang giua do nhay phim, do muot hanh trinh va kha nang kiem soat khi bam lien tuc. O bo pack co san, san pham phu hop cho nguoi dung muon test truoc khi build full keyboard, hoac thay tung cum phim quan trong de toi uu trai nghiem. Neu ban uu tien game can toc do cao, nen ket hop voi spring luc vua va keycap profile quen tay de giam sai so input. Neu ban uu tien typing dai gio, hay can nhac tuning co ban de giam tieng rung va giu cam giac on dinh. Nguon tham khao: N/A.",
